mapper.select:
select s.id, s.stock_code, s.stock_name, s.market,
s.pe_ratio, s.circ_market_cap,
s.current_price, s.change_rate, s.price_change, s.speed,
s.turnover_rate, s.volume_ratio, s.amplitude,
s.turnover_amount, s.circulating_shares,
s.create_by, s.create_time, s.update_by, s.update_time, s.remark,
ifnull(ls.limit_up_count, 0) as limit_up_count,
lr.last_limit_up_date
from stock s
left join stock_limit_up_stat ls on ls.stock_code = s.stock_code
left join (
    select secu_code, max(trade_date) as last_limit_up_date
    from stock_limit_up_record
    where secu_code is not null and secu_code != ''
    group by secu_code
) lr on lr.secu_code = s.stock_code

     and s.stock_code = #{stockCode}
     and s.stock_name like concat('%', #{stockName}, '%')
     and s.market = #{market}

        and EXISTS (
        select 1 from stock_plate_stock sps
        inner join stock_plate sp on sps.plate_code = sp.plate_code
        where sps.stock_code = s.stock_code and sp.plate_type = 'INDUSTRY'
        and sp.id in

            #{industryId}

        )


        and EXISTS (
        select 1 from stock_plate_stock sps2
        inner join stock_plate sp2 on sps2.plate_code = sp2.plate_code
        where sps2.stock_code = s.stock_code and sp2.plate_type = 'CONCEPT'
        and sp2.id in

            #{conceptId}

        )


        and EXISTS (
            select 1 from stock_group_stock sgs
            where sgs.stock_code = s.stock_code and sgs.group_id in

                #{groupId}

        )


        and ifnull(ls.limit_up_count, 0) >= #{minLimitUpCount}


        and exists (
            select 1 from stock_limit_up_record lr
            where lr.secu_code = s.stock_code
            and lr.trade_date = (select max(trade_date) from stock_limit_up_record)
        )


        and s.current_price >= #{minCurrentPrice}


        and s.current_price <= #{maxCurrentPrice}


        and s.change_rate >= #{minChangeRate}


        and s.change_rate <= #{maxChangeRate}


        and s.turnover_rate >= #{minTurnoverRate}


        and s.turnover_rate <= #{maxTurnoverRate}


        and s.volume_ratio >= #{minVolumeRatio}


        and s.volume_ratio <= #{maxVolumeRatio}


        and s.turnover_amount >= #{minTurnoverAmount}


        and s.turnover_amount <= #{maxTurnoverAmount}


order by ifnull(ls.limit_up_count, 0) desc, s.stock_code asc

mapper.update:
update stock
stock_code = #{stockCode}, stock_name = #{stockName}, market = #{market}, pe_ratio = #{peRatio}, circ_market_cap = #{circMarketCap}, current_price = #{currentPrice}, change_rate = #{changeRate}, price_change = #{priceChange}, speed = #{speed}, turnover_rate = #{turnoverRate}, volume_ratio = #{volumeRatio}, amplitude = #{amplitude}, turnover_amount = #{turnoverAmount}, circulating_shares = #{circulatingShares}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where id = #{id}

mapper.select:

where market in

    #{market}

order by id desc
